INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Multi-Threading immer mehrere Prozessoren erfordert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Läuft auch auf einem Kern"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Multi-Threading in einer IT-Anwendung einsetze?', 3, '[{"text": "Thread-Synchronisation", "correct": true, "because": "Vermeidet Konflikte"}, {"text": "Schnellste Implementierung", "correct": false, "because": "Korrektheit zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat Multi-Threading in der IT?', 5, '[{"text": "Parallele Ausführung", "correct": true, "because": "Mehrere Threads"}, {"text": "Ressourcennutzung", "correct": true, "because": "Optimiert CPU"}, {"text": "Büromöbel", "correct": false, "because": "Kein Merkmal"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Multi-Threading erhöht die Leistung. b) Es vermeidet immer Konflikte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Konflikte möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Multi-Threading in einer Anwendung einsetze?', 4, '[{"text": "Thread-Sicherheit", "correct": false, "because": "Vermeidet Konflikte"}, {"text": "Prozessoranzahl", "correct": false, "because": "Beeinflusst Leistung"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Multi-Threading nur für Mehrkernprozessoren geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch auf Einkern"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Multi-Threading in einer IT-Anwendung?', 3, '[{"text": "Leistungssteigerung", "correct": true, "because": "Parallele Ausführung"}, {"text": "Schnellste Entwicklung", "correct": false, "because": "Effizienz zählt"}, {"text": "Weniger Threads", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken gehören zu Multi-Threading?', 5, '[{"text": "Synchronisation", "correct": true, "because": "Koordiniert Threads"}, {"text": "Thread-Pools", "correct": true, "because": "Managed Threads"}, {"text": "Büroplanung", "correct": false, "because": "Irrelevant"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Multi-Threading kann Deadlocks verursachen. b) Es ist immer einfach zu implementieren. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Komplexität möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Multi-Threading in einer Anwendung zu nutzen?', 4, '[{"text": "Thread-Management", "correct": false, "because": "Steuert Ablauf"}, {"text": "Synchronisationsmechanismen", "correct": false, "because": "Vermeiden Konflikte"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Multi-Threading immer effizienter als Single-Threading?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Aufgabe"}, {"text": "Ja", "correct": false, "because": "Nicht immer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Multi-Threading?', 4, '[{"text": "Parallele Verarbeitung", "correct": true, "because": "Steigert Leistung"}, {"text": "Bessere Ressourcennutzung", "correct": true, "because": "Optimiert CPU"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Multi-Threading nur für komplexe Anwendungen geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch einfache Aufgaben"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Multi-Threading effektiv zu implementieren?', 3, '[{"text": "Mutex", "correct": true, "because": "Sichert Threads"}, {"text": "Schnellste Programmierung", "correct": false, "because": "Korrektheit zählt"}, {"text": "Bunte Oberfläche", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Multi-Threading nutzt mehrere Threads pro Prozess. b) Es vermeidet immer Deadlocks.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Deadlocks möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei Multi-Threading?', 5, '[{"text": "Synchronisation", "correct": true, "because": "Vermeidet Konflikte"}, {"text": "Thread-Anzahl", "correct": true, "because": "Beeinflusst Leistung"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Multi-Threading implementiere?', 3, '[{"text": "Thread-Prioritäten", "correct": false, "because": "Steuern Ablauf"}, {"text": "Ressourcenkonflikte", "correct": false, "because": "Zu vermeiden"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht Multi-Threading immer die Leistung?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig von Aufgabe"}, {"text": "Ja", "correct": false, "because": "Nicht immer"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Multi-Threading nur für Mehrkern-CPUs geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Einkern möglich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für Multi-Threading?', 4, '[{"text": "Thread-Synchronisation", "correct": true, "because": "Sichert Korrektheit"}, {"text": "Schnellste Implementierung", "correct": false, "because": "Effizienz zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
